1	/**
2	 * The typing-side half of @-mentions.
3	 *
4	 * `@/lib/mentions` owns what a finished comment body *means* (which users it
5	 * mentions); this module owns what the caret is currently doing — where the
6	 * active `@token` starts, what it filters to, and what the body looks like
7	 * once a suggestion is accepted. Splitting it that way keeps the textarea from
8	 * re-deriving the parsing rules the server also applies.
9	 */
10	import type { MemberWithUser } from "@/types/member";
11	
12	/** An in-progress mention: `@` plus the characters typed after it. */
13	export interface MentionQuery {
14	  /** Index of the `@` in the body. */
15	  readonly start: number;
16	  /** Index just past the last typed character. */
17	  readonly end: number;
18	  /** The text after `@`, lowercased for matching. */
19	  readonly query: string;
20	}
21	
22	const MENTION_CHARS = /^[a-zA-Z0-9._-]*$/;
23	
24	/**
25	 * Finds the mention the caret sits inside, or `null` when the caret is not in
26	 * one. A mention only starts at the beginning of the body or after
27	 * whitespace, so an email address never opens the autocomplete.
28	 */
29	export function findMentionQuery(
30	  body: string,
31	  caret: number,
32	): MentionQuery | null {
33	  const upTo = body.slice(0, Math.max(0, Math.min(caret, body.length)));
34	  const at = upTo.lastIndexOf("@");
35	  if (at === -1) return null;
36	
37	  const before = at === 0 ? "" : upTo[at - 1] ?? "";
38	  if (before.length > 0 && !/\s/.test(before)) return null;
39	
40	  const typed = upTo.slice(at + 1);
41	  if (!MENTION_CHARS.test(typed)) return null;
42	
43	  return { start: at, end: upTo.length, query: typed.toLowerCase() };
44	}
45	
46	/** The handle Taskflow mentions people by: the local part of their email. */
47	export function mentionHandle(member: MemberWithUser): string {
48	  const [local = member.user.name] = member.user.email.split("@");
49	  return local.toLowerCase();
50	}
51	
52	/** Members whose handle or display name matches the in-progress query. */
53	export function matchMembers(
54	  members: readonly MemberWithUser[],
55	  query: string,
56	  limit = 5,
57	): readonly MemberWithUser[] {
58	  const needle = query.toLowerCase();
59	  const matches =
60	    needle.length === 0
61	      ? members
62	      : members.filter(
63	          (member) =>
64	            mentionHandle(member).includes(needle) ||
65	            member.user.name.toLowerCase().includes(needle),
66	        );
67	  return matches.slice(0, limit);
68	}
69	
70	/** Replaces the in-progress mention with the chosen member's handle. */
71	export function applyMention(
72	  body: string,
73	  mention: MentionQuery,
74	  member: MemberWithUser,
75	): { body: string; caret: number } {
76	  const inserted = `@${mentionHandle(member)} `;
77	  const next = body.slice(0, mention.start) + inserted + body.slice(mention.end);
78	  return { body: next, caret: mention.start + inserted.length };
79	}
80

