function isPastEditWindow(comment: Comment): boolean {
  // The window is counted from the original posting, never from a later
  // edit — otherwise each edit would grant the author a fresh fifteen
  // minutes, in effect never closing.
  const posted = new Date(comment.createdAt).getTime();
  return Date.now() - posted > EDIT_WINDOW_MS;
}

/**
 * Union of the ids the client already resolved (optimistic UI) and the ones
 * parsed out of the body server-side. The server list wins on disagreement.
 * Every active member is scanned, however many pages that takes, so a
 * long-standing workspace does not lose mentions of its oldest members past
 * the first page.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
  authorId: UserId,
): Promise<readonly UserId[]> {
  const members = await listAllActiveMembers(orgId);

  const resolved = resolveMentions(body, members, authorId);
  const known = new Set(members.map((member) => member.userId));

  return [
    ...new Set([...resolved, ...clientProvided.filter((id) => known.has(id))]),
  ];
}

async function listAllActiveMembers(
  orgId: OrgId,
): Promise<readonly MemberWithUser[]> {
  const members: MemberWithUser[] = [];
  let cursor: string | null = null;

  for (;;) {
    const page = await memberRepo.listMembers({
      orgId,
      status: "active",
      limit: MENTION_LOOKUP_PAGE_SIZE,
      cursor,
    });
    members.push(...page.items);
    if (page.nextCursor === null) break;
    cursor = page.nextCursor;
  }

  return members;
}

