subscribe("comment.created", async (payload) => {
  const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
  const watchers = issue
    ? [
        issue.authorId,
        ...(issue.assigneeId ? [issue.assigneeId] : []),
        ...(payload.parentAuthorId ? [payload.parentAuthorId] : []),
      ]
    : payload.parentAuthorId
      ? [payload.parentAuthorId]
      : [];

  const mentioned = new Set(payload.mentionedUserIds);
  // A mention alert takes precedence: anyone already getting one must not
  // also get a plain "comment was added" alert for the same comment.
  const commentWatchers = watchers.filter((id) => !mentioned.has(id));

  if (commentWatchers.length > 0) {
    await notify(payload.orgId, "comment_created", commentWatchers, {
      title: "New comment",
      body: `A comment was added to issue ${payload.issueId}`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
    });
  }

  if (payload.mentionedUserIds.length > 0) {
    await notify(
      payload.orgId,
      "comment_mention",
      payload.mentionedUserIds,
      {
        title: "You were mentioned",
        body: `You were mentioned on issue ${payload.issueId}`,
        href: `/issues/${payload.issueId}`,
        actorId: payload.actorId,
      },
    );
  }
});

subscribe("comment.updated", async (payload) => {
  if (payload.newlyMentionedUserIds.length === 0) return;
  await notify(
